begin
 if current_setting('transaction_read_only') is distinct from 'on'
  or current_setting('transaction_isolation') is distinct from 'repeatable read'
  or jsonb_array_length(source_manifest)<>44 or jsonb_array_length(new_functions)<>23
  or (select count(distinct f.value->>'signature') from jsonb_array_elements(source_manifest) f(value))<>44
  or (select count(distinct f.value->>'signature') from jsonb_array_elements(new_functions) f(value))<>23
  then raise exception 'JD_CATALOG_CONTRACT_INVALID' using errcode='23514';end if;
 if (select count(*) from pg_catalog.pg_roles where rolname in('anon','authenticated','service_role'))<>3 then
  raise exception 'JD_CATALOG_ROLE_MISSING' using errcode='23514';end if;
 -- The same exact canonical source anchor owns the frozen Native authority.
 -- No hosted role name, client claim, CSET or target-approval label is substituted.
 select p.proowner into expected_owner from pg_catalog.pg_proc p
  where p.oid=to_regprocedure('private.canonical_correction_write_ready()');
 if expected_owner is null or not exists(select 1 from pg_catalog.pg_roles r where r.oid=expected_owner)
  or expected_owner in(select oid from pg_catalog.pg_roles where rolname in('anon','authenticated','service_role')) then
  raise exception 'JD_CATALOG_OWNER_INVALID' using errcode='23514';end if;
 -- Catch extra overloads in the new authority namespace, not only missing rows.
 if (select count(*) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace
   where (n.nspname='private' and left(p.proname,10)='jd_clause_')
    or (n.nspname='public' and p.proname in('apply_jd_clause_order_action','read_jd_clause_order_readiness')))<>23 then
  raise exception 'JD_CATALOG_NEW_FUNCTION_SET_DRIFT' using errcode='23514';end if;
 -- 44 exact source expectations plus the externally pinned checker itself.
 for item in select f.value from jsonb_array_elements(source_manifest||jsonb_build_array(
   (select f.value from jsonb_array_elements(new_functions) f(value) where f.value->>'signature'='private.jd_clause_schema_ready()'))) f(value) loop
  select * into routine from pg_catalog.pg_proc where oid=to_regprocedure(item->>'signature');
  if not found or routine.prokind<>'f' or routine.proretset or routine.proowner<>expected_owner
   or routine.prorettype<>to_regtype(item->>'result') or routine.provolatile<>item->>'volatility'
   or routine.prosecdef is distinct from (item->>'definer')::boolean or routine.proisstrict is distinct from (item->>'strict')::boolean
   or routine.prolang<>(select oid from pg_catalog.pg_language where lanname=item->>'language')
   or routine.proconfig is distinct from array['search_path=""']
   or encode(extensions.digest(convert_to(routine.prosrc,'UTF8'),'sha256'),'hex') is distinct from item->>'sha256' then
   raise exception 'JD_CATALOG_FUNCTION_DRIFT' using errcode='23514';end if;
  select f.value into new_item from jsonb_array_elements(new_functions) f(value) where f.value->>'signature'=item->>'signature';
  if new_item is not null and (routine.pronargdefaults<>0 or routine.proargdefaults is not null
    or routine.proargmodes is not null or routine.proallargtypes is not null or routine.provariadic<>0
    or to_jsonb(coalesce(routine.proargnames,array[]::text[])) is distinct from new_item->'argNames') then
   raise exception 'JD_CATALOG_ARGUMENT_DRIFT' using errcode='23514';end if;
  -- A schema-ready source may allow optional service execution; Stage A does
  -- not. All new helpers and the writer stay denied, with metadata the sole exception.
  service_allowed:=case when new_item is not null then new_item->>'acl'='metadata' else item->>'acl' in('optional_service','metadata') end;
  if exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a
   where a.grantee<>routine.proowner and (not service_allowed or a.grantee<>(select oid from pg_catalog.pg_roles where rolname='service_role')
    or a.privilege_type<>'EXECUTE' or a.is_grantable)) then
   raise exception 'JD_CATALOG_ACL_DRIFT' using errcode='42501';end if;
  foreach role_name in array array['anon','authenticated','service_role'] loop
   if has_function_privilege(role_name,routine.oid,'EXECUTE') and (role_name<>'service_role' or not service_allowed) then
    raise exception 'JD_CATALOG_EFFECTIVE_PRIVILEGE_DRIFT' using errcode='42501';end if;
  end loop;
  service_granted:=exists(select 1 from aclexplode(coalesce(routine.proacl,acldefault('f',routine.proowner))) a
   where a.grantee=(select oid from pg_catalog.pg_roles where rolname='service_role') and a.privilege_type='EXECUTE' and not a.is_grantable);
  if has_function_privilege('service_role',routine.oid,'EXECUTE') is distinct from (service_allowed and service_granted)
   or ((case when new_item is not null then new_item->>'acl' else item->>'acl' end)='metadata' and not service_granted) then
   raise exception 'JD_CATALOG_DIRECT_PRIVILEGE_DRIFT' using errcode='42501';end if;
 end loop;
 -- Only invoke routines after their actual source, attributes, owner and ACLs
 -- match the fixed catalogue. These functions read schema metadata, not candidate data.
 if private.jd_clause_schema_ready() is not true then
  raise exception 'JD_CATALOG_SCHEMA_NOT_READY' using errcode='23514';end if;
 metadata:=public.read_jd_clause_order_readiness();
 if metadata is distinct from expected_profile||jsonb_build_object('schemaReady',true,'writerExecutable',false)
  or has_function_privilege('service_role','public.apply_jd_clause_order_action(uuid,uuid,jsonb,text)','EXECUTE') then
  raise exception 'JD_CATALOG_METADATA_OR_WRITER_DRIFT' using errcode='23514';end if;
end;
$jd_catalog_verify$;

-- Metadata-only result. No candidate, Auth or storage rows are read or emitted.
select jsonb_build_object('schemaVersion','jd-clause-order-catalogue-verification/1.0.0',
 'newFunctionCount',23,'sourceManifestCount',44,'readiness',public.read_jd_clause_order_readiness()) as catalogue_verification;
commit;
